import requests
from pyspark.sql.functions import udf
from pyspark.sql.types import DoubleType

PRICING_URL = 'https://pricing-svc.nordgrid.internal/multiplier'

@udf(returnType=DoubleType())
def get_multiplier(customer_type, region):
    resp = requests.get(PRICING_URL, params={'ct': customer_type, 'rg': region}, timeout=2)
    return float(resp.json()['multiplier'])

df = df.withColumn('multiplier', get_multiplier('customer_type', 'region'))
